`timescale 1ns / 1ps
// Repro for bucket PULSE_WIDTH: each period the output is high for exactly duty cycles.
module tb;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg  [3:0] duty = 4'd0;
    wire       pwm;
    integer    passed = 0;
    integer    failed = 0;
    integer    cyc = 0;
    integer    t0, t1, i;
    reg        done = 1'b0;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;
    always @(posedge clk) cyc <= cyc + 1;

    task chk_eq(input [8*32-1:0] label, input integer got, input integer exp);
        begin
            if (got == exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("FAIL [%0s] got %0d expected %0d", label, got, exp);
            end
        end
    endtask

    task finish_tb;
        begin
            if (!done) begin
                done = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    initial begin
        #100000;
        $display("FAIL [WATCHDOG] pwm stopped toggling");
        failed = failed + 1;
        finish_tb;
    end

    task measure(input integer d);
        begin
            duty = d;
            repeat (40) @(posedge clk);
            for (i = 0; i < 3; i = i + 1) begin
                @(posedge pwm); #1 t0 = cyc;
                @(negedge pwm); #1 t1 = cyc;
                chk_eq("PULSE_WIDTH_EQ_DUTY", t1 - t0, d);
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        duty = 4'd3;
        rst  = 1'b1;
        repeat (3) @(posedge clk);
        @(negedge clk) rst = 1'b0;
        measure(3);
        measure(5);
        finish_tb;
    end
endmodule
=== END FILE ===

=== FILE: tb/repro_duty_update.v ===
`timescale 1ns / 1ps
// Repro for bucket DUTY_UPDATE: a duty change in the middle of a period
// must take effect only in the next period.
module tb;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg  [3:0] duty = 4'd0;
    wire       pwm;
    integer    passed = 0;
    integer    failed = 0;
    integer    gap, w;
    reg        done = 1'b0;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task chk(input cond, input [8*32-1:0] label, input integer got);
        begin
            if (cond) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("FAIL [%0s] got %0d", label, got);
            end
        end
    endtask

    task finish_tb;
        begin
            if (!done) begin
                done = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    initial begin
        #100000;
        $display("FAIL [WATCHDOG] pwm stopped toggling");
        failed = failed + 1;
        finish_tb;
    end

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        duty = 4'd2;
        rst  = 1'b1;
        repeat (3) @(posedge clk);
        @(negedge clk) rst = 1'b0;
        repeat (40) @(posedge clk);
        // pwm just fell: we are in the low part of a period with duty 2.
        @(negedge pwm);
        @(negedge clk) duty = 4'd6;
        gap = 0;
        while (pwm == 1'b0 && gap < 20) begin
            @(posedge clk); #1;
            gap = gap + 1;
        end
        // The rest of this period must stay low (period 8, duty 2 leaves about 6 low cycles).
        chk(gap >= 4 && gap < 20, "DUTY_MIDPERIOD_HELD_LOW", gap);
        w = 0;
        while (pwm == 1'b1 && w < 20) begin
            @(posedge clk); #1;
            w = w + 1;
        end
        // The next period must use the new duty (6).
        chk(w >= 5 && w <= 7, "DUTY_NEXT_PERIOD_APPLIED", w);
        finish_tb;
    end
endmodule
=== END FILE ===

