// Repro for bucket PERIOD: the output must repeat every PERIOD clock cycles.
module tb;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg  [3:0] duty = 4'd0;
    wire       pwm;
    integer    passed = 0;
    integer    failed = 0;
    integer    cyc = 0;
    integer    t_prev, t_now, i;
    reg        done = 1'b0;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;
    always @(posedge clk) cyc <= cyc + 1;

    task chk_eq(input [8*32-1:0] label, input integer got, input integer exp);
        begin
            if (got == exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("FAIL [%0s] got %0d expected %0d", label, got, exp);
            end
        end
    endtask

    task finish_tb;
        begin
            if (!done) begin
                done = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    initial begin
        #100000;
        $display("FAIL [WATCHDOG] pwm stopped toggling");
        failed = failed + 1;
        finish_tb;
    end

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        duty = 4'd3;
        rst  = 1'b1;
        repeat (3) @(posedge clk);
        @(negedge clk) rst = 1'b0;
        repeat (30) @(posedge clk);
        @(posedge pwm); #1 t_prev = cyc;
        for (i = 0; i < 4; i = i + 1) begin
            @(posedge pwm); #1 t_now = cyc;
            chk_eq("PERIOD_RISE_TO_RISE", t_now - t_prev, 8);
            t_prev = t_now;
        end
        finish_tb;
    end
endmodule
